//! Declares project-wide `cfg` aliases so platform checks read cleanly.
//!
//! Raw predicates such as `#[cfg(target_os = "macos")]` are noisy and easy to
//! mistype once a crate grows past one or two targets. Instead of repeating
//! them at every use site, they are defined exactly once here and expanded to
//! short aliases like `#[cfg(macos)]`.
//!
//! `cfg_aliases!` also emits `cargo:rustc-check-cfg`, so the `unexpected_cfgs`
//! lint understands these names and will still catch genuine typos.

use cfg_aliases::cfg_aliases;

fn main() {
    println!("cargo:rerun-if-changed=build.rs");

    cfg_aliases! {
        // Operating-system families.
        macos:   { target_os = "macos" },
        linux:   { target_os = "linux" },
        android: { target_os = "android" },
        ios:     { target_os = "ios" },

        // WebAssembly targets.
        wasm: { target_arch = "wasm32" },

        // Capability groups, built from the families above.
        desktop: { any(windows, macos, linux) },
        mobile:  { any(android, ios) },
        has_threads: { any(windows, macos, linux, android, target_os = "freebsd") },

        // Pointer widths.
        ptr_64: { target_pointer_width = "64" },
        ptr_32: { target_pointer_width = "32" },
    }
}

//! Cross-platform helpers built around clean, readable conditional
//! compilation.
//!
//! Raw platform predicates such as `#[cfg(target_os = "windows")]` become
//! noisy once a crate serves more than one or two targets. This crate keeps
//! that noise out of the implementation:
//!
//! 1. `build.rs` defines short aliases (`macos`, `linux`, `desktop`, `wasm`,
//!    ...) with `cfg_aliases!`, so a use site reads `#[cfg(desktop)]` instead
//!    of repeating long `any(...)` predicates.
//! 2. [`cfg_if!`] selects whole blocks at compile time when several mutually
//!    exclusive branches are involved, instead of stacking several `#[cfg]`
//!    attributes on one item.
//!
//! The result is that each platform decision lives in exactly one place.
//!
//! # Example
//!
//! ```
//! use crossplat::platform;
//!
//! let here = platform::current();
//! assert_eq!(here, platform::current());
//! assert!(!here.name().is_empty());
//! ```

pub mod paths;
pub mod platform;

pub use platform::Platform;

//! Compile-time platform detection.
//!
//! Every predicate used here comes from a `cfg` alias declared in `build.rs`,
//! which keeps the branches short and self-documenting.

use cfg_if::cfg_if;

/// The coarse-grained platform a build targets.
///
/// The granularity is intentional: dependent code usually cares whether it is
/// on Windows, a Unix, mobile, or the web, not about the exact OS version.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum Platform {
    /// Microsoft Windows.
    Windows,
    /// Apple macOS.
    MacOs,
    /// Linux.
    Linux,
    /// Google Android.
    Android,
    /// Apple iOS.
    Ios,
    /// A 32-bit WebAssembly target.
    Wasm,
    /// Any target this crate does not special-case.
    Other,
}

impl Platform {
    /// Returns the platform this crate was compiled for.
    ///
    /// The branch is selected at compile time, so the result is a constant.
    #[must_use]
    pub const fn current() -> Self {
        cfg_if! {
            if #[cfg(windows)] {
                Self::Windows
            } else if #[cfg(macos)] {
                Self::MacOs
            } else if #[cfg(linux)] {
                Self::Linux
            } else if #[cfg(android)] {
                Self::Android
            } else if #[cfg(ios)] {
                Self::Ios
            } else if #[cfg(wasm)] {
                Self::Wasm
            } else {
                Self::Other
            }
        }
    }

    /// Returns the lowercase, stable name of the platform.
    #[must_use]
    pub const fn name(self) -> &'static str {
        match self {
            Self::Windows => "windows",
            Self::MacOs => "macos",
            Self::Linux => "linux",
            Self::Android => "android",
            Self::Ios => "ios",
            Self::Wasm => "wasm",
            Self::Other => "other",
        }
    }

    /// Returns `true` for platforms with a windowing desktop environment.
    #[must_use]
    pub const fn is_desktop(self) -> bool {
        matches!(self, Self::Windows | Self::MacOs | Self::Linux)
    }

    /// Returns `true` for mobile operating systems.
    #[must_use]
    pub const fn is_mobile(self) -> bool {
        matches!(self, Self::Android | Self::Ios)
    }
}

/// Returns `true` when compiled for a desktop platform.
///
/// This uses the `desktop` alias directly because a single boolean is all the
/// caller needs.
#[must_use]
pub const fn is_desktop_build() -> bool {
    cfg!(desktop)
}

/// Returns `true` when compiled for a mobile platform.
#[must_use]
pub const fn is_mobile_build() -> bool {
    cfg!(mobile)
}

/// Returns `true` when the target supports threads.
#[must_use]
pub const fn has_threads() -> bool {
    cfg!(has_threads)
}

/// Returns the pointer width of the target in bits.
///
/// Returns `0` for the rare target whose width is neither 32 nor 64 bits.
#[must_use]
pub const fn pointer_width() -> u32 {
    cfg_if! {
        if #[cfg(ptr_64)] {
            64
        } else if #[cfg(ptr_32)] {
            32
        } else {
            0
        }
    }
}

#[cfg(test)]
mod tests {
    use super::Platform;

    #[test]
    fn detection_matches_the_alias_groupings() {
        assert_eq!(is_desktop_build(), Platform::current().is_desktop());
        assert_eq!(is_mobile_build(), Platform::current().is_mobile());
    }

    #[test]
    fn pointer_width_matches_the_standard_library() {
        assert_eq!(pointer_width(), usize::BITS);
    }

    #[test]
    fn name_is_never_empty() {
        assert!(!Platform::current().name().is_empty());
    }
}

//! Per-platform path conventions.
//!
//! This module demonstrates a *behavioural* platform split: the same public
//! function has a different body on each target, selected with [`cfg_if!`].

use cfg_if::cfg_if;

/// Returns the separator between path components on this platform.
#[must_use]
pub const fn separator() -> char {
    cfg_if! {
        if #[cfg(windows)] {
            '\\'
        } else {
            '/'
        }
    }
}

/// Returns the separator between entries of a `PATH`-like environment
/// variable on this platform.
#[must_use]
pub const fn env_separator() -> char {
    cfg_if! {
        if #[cfg(windows)] {
            ';'
        } else {
            ':'
        }
    }
}

/// Returns the conventional extension for a dynamically linked library,
/// without a leading dot.
#[must_use]
pub const fn dynamic_library_extension() -> &'static str {
    cfg_if! {
        if #[cfg(windows)] {
            "dll"
        } else if #[cfg(macos)] {
            "dylib"
        } else if #[cfg(linux)] {
            "so"
        } else {
            "bin"
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{dynamic_library_extension, env_separator, separator};

    #[cfg(windows)]
    #[test]
    fn windows_conventions() {
        assert_eq!(separator(), '\\');
        assert_eq!(env_separator(), ';');
        assert_eq!(dynamic_library_extension(), "dll");
    }

    #[cfg(macos)]
    #[test]
    fn macos_conventions() {
        assert_eq!(separator(), '/');
        assert_eq!(env_separator(), ':');
        assert_eq!(dynamic_library_extension(), "dylib");
    }

    #[cfg(linux)]
    #[test]
    fn linux_conventions() {
        assert_eq!(separator(), '/');
        assert_eq!(env_separator(), ':');
        assert_eq!(dynamic_library_extension(), "so");
    }
}

//! Integration tests exercise the crate exactly as a downstream user would,
//! which also proves the public `cfg` aliases survive across crate boundaries.

use crossplat::{paths, platform, Platform};

#[test]
fn detected_platform_is_consistent_across_the_public_api() {
    let here = Platform::current();

    assert_eq!(here, platform::current());
    assert_eq!(here.name(), here.name());
    assert_eq!(platform::is_desktop_build(), here.is_desktop());
    assert_eq!(platform::is_mobile_build(), here.is_mobile());
}

#[test]
fn path_conventions_are_internally_consistent() {
    let separator = paths::separator();
    let env_separator = paths::env_separator();

    assert!(separator == '/' || separator == '\\');
    assert!(env_separator == ':' || env_separator == ';');
    assert!(!paths::dynamic_library_extension().is_empty());
}

